/// <summary>
/// Enables delegation buttons according to input
/// Dialog = input; Cancel != input
/// </summary>
/// <param name = "_enabled">NoYes</param>
public void avaEnableDelegationButtons(NoYes _enabled)
{
    AVAInventSiteDelegateDialog.enabled(_enabled);
    AVAInventSiteDelegateCancel.enabled(!_enabled);
    AVASalesOrderDelegationReportActionPreview.enabled(!_enabled);
    AVASalesOrderDelegationReportAction.enabled(!_enabled);
}

/// <summary>
/// Disables delegation buttons
/// </summary>
public void avaDisableDelegationButtons()
{
    AVAInventSiteDelegateDialog.enabled(NoYes::No);
    AVAInventSiteDelegateCancel.enabled(NoYes::No);
    AVASalesOrderDelegationReportActionPreview.enabled(NoYes::No);
    AVASalesOrderDelegationReportAction.enabled(NoYes::No);
}

/// <summary>
///     AVA <c>initFrmValues</c> method.
/// </summary>
public void initFrmValues()
{
    frmArgs                 = this.args();
    frmAVAWorkerInventSite  = AVAWorkerInventSite::find(HcmWorker::findByPerson(DirPersonUser::find(curUserId()).PersonParty).PersonnelNumber);
    frmInventSiteId         = frmAVAWorkerInventSite.InventSiteId;
}

/// <summary>
///     AVA <c>initQueryRange</c> method.
/// </summary>
public void initQueryRange()
{
    QueryBuildDataSource    salesTableQBDS;
    AVAEDISalesType         locAVAEDISalesTypeQueryRange;
    InventSiteId            locInventSiteId;

    #define.AVAStartsWithEDI('EDI*')

    locAVAEDISalesTypeQueryRange    = #AVAStartsWithEDI;

    salesTableQBDS  = SalesTable_DS.query().dataSourceName(SalesTable_DS.name());

    if (frmArgs)
    {
        if (frmArgs.menuItemName()      == menuitemDisplayStr(SalesTableListPage)   )
        {
            locInventSiteId = frmInventSiteId;
            SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, InventSiteId)).value(queryValue(locInventSiteId));
            SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, AVADelegatedToAgent)).value(queryValue(NoYes::No));
        }
        else if (frmArgs.menuItemName() == menuitemDisplayStr(AVASalesTableListPageEDI) )
        {
            locInventSiteId = '';
            SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, SalesOriginId)).value(SysQuery::valueLikeAfter(locAVAEDISalesTypeQueryRange));
            SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, AVADelegatedToAgent)).value(queryValue(NoYes::No));
        }
        else if (frmArgs.menuItemName() == menuItemDisplayStr(AVASalesTableListPageDelegation) )
        {
            locInventSiteId = frmInventSiteId;
            if(locInventSiteId)
            {
                SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, InventSiteId)).value(queryValue(locInventSiteId));
            }

            SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, AVADelegatedToAgent)).value(queryValue(NoYes::Yes));
        }
        else
        {
            locInventSiteId = frmInventSiteId;
            if(locInventSiteId)
            {
                SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, InventSiteId)).value(queryValue(locInventSiteId));
            }

        }
    }
    if(!locInventSiteId)
    {
        SysQuery::findOrCreateRange(salesTableQBDS, fieldNum(SalesTable, InventSiteId)).value(SysQueryRangeUtil::valueUnlimited());
    }
    AVAInventSiteId.text(locInventSiteId);
}
